        /* preserve_case = TRUE; -- moot since we're jumping to the end */
        C.Sprintf(prompt, "%s ", query);
        C.custompline(C.OVERRIDE_MSGTYPE | C.SUPPRESS_HISTORY, "%s", prompt);
